import React from 'react';

import { useNavigate } from 'react-router-dom';

import { getRadishStat } from '@apps/Hiking/@services/hikingRadish.service';
import { IHikingRadishStat } from '@apps/Hiking/@types/hikingRadish.types';
import Page from '@components/Page';
import { declOfNum } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCard from '@ui-kit/Card';
import PohCheckbox from '@ui-kit/Checkbox';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';

import nenadotak from '../../../../img/nenado-tak.jpg';

const RadishPage = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IHikingRadishStat[]>([]);
  const [comments, setComments] = React.useState<string[]>([]);
  const [hikingCounts, setHikingCounts] = React.useState<Record<number, number>>({});
  const [showCoolMans, setShowCoolMans] = React.useState(window.location.hash === '#all');

  const navigate = useNavigate();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getRadishStat();
      setData(res.users);
      setComments(res.comments);
      setHikingCounts(res.hikingCounts);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PohLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <Page title="Редиски">
      <figure
        onDoubleClick={() => {
          setShowCoolMans((c) => {
            window.location.hash = c ? '' : '#all';
            return !c;
          });
        }}
      >
        <blockquote className="blockquote">
          <p>Редиски - это люди которые отказались от какого-то из походов.</p>
        </blockquote>
        <figcaption className="blockquote-footer">
          Из этого списки можно исчезнуть если количество пропущенных походов будет меньше 10%
        </figcaption>
      </figure>

      <PohCheckbox
        checked={showCoolMans}
        onChange={setShowCoolMans}
        label="Показать реабилитированных"
      />

      <PohRow>
        <PohCol sm={7} className="d-flex flex-wrap" style={{ gap: 12 }}>
          {data.map((item) => {
            const pct = (item.count / (hikingCounts[item.user.id] ?? 1)) * 100;
            if (!showCoolMans && pct < 10) return null;
            return (
              <PohCard
                style={{ width: 200 }}
                key={item.user.id}
                className="text-center"
                onClick={() => {
                  navigate(`/radish/${item.user.id}`);
                }}
              >
                <PohBadge
                  variant={
                    pct > 50
                      ? BadgeVariant.Danger
                      : pct < 10
                        ? BadgeVariant.Success
                        : BadgeVariant.Warning
                  }
                  className="float-start"
                  title={[
                    `Пропущено ${item.count}`,
                    `Завершено ${hikingCounts[item.user.id] ?? 0}`,
                  ].join('\n')}
                >
                  {round(pct, 2)}%
                </PohBadge>
                <PohBadge className="float-end">
                  {item.count} {declOfNum(item.count, ['раз', 'раза', 'раз'])}
                </PohBadge>
                <PohAva
                  src={item.user.photo}
                  alt={[item.user.name, item.user.surname].join(' ')}
                  className="me-2"
                  width={120}
                />

                <h5>
                  {item.user.name}
                  <br />
                  {item.user.surname}
                </h5>
                <small>{item.lastDate.toLocaleString()}</small>
              </PohCard>
            );
          })}
        </PohCol>
        <PohCol sm={5} className="text-end">
          <img src={nenadotak} alt="не надо так..." width={180} />
          <hr />
          <h3>Что говорят...</h3>

          {comments.map((c) => {
            return (
              <blockquote key={c} className="border-start border-start-info">
                <em>{c}</em>
              </blockquote>
            );
          })}
        </PohCol>
      </PohRow>
    </Page>
  );
};

export default RadishPage;
